{
  "name": "@pi-swarm/agents",
  "private": true,
  "type": "module",
  "scripts": {
    "build": "tsc -p tsconfig.json",
    "test": "vitest run test"
  },
  "devDependencies": {
    "@types/node": "^22.0.0",
    "typescript": "^5.9.0",
    "vitest": "^3.2.0"
  }
}

import { createHash } from "node:crypto";
import { mkdir } from "node:fs/promises";
import { execFile } from "node:child_process";
import { promisify } from "node:util";

const execFileAsync = promisify(execFile);
export type AgentStatus = "queued" | "running" | "completed" | "failed" | "cancelled";
export interface Profile { name: string; systemPrompt?: string; capabilities?: string[]; tools?: string[]; }
export interface Preset extends Profile { provider?: string; model?: string; concurrency?: number; worktree?: boolean; }
export interface AgentSpec { id?: string; parentId?: string; parentSessionId?: string; sessionId?: string; task: string; provider?: string; model?: string; profile?: string; preset?: string; capabilities?: string[]; worktree?: string | boolean; background?: boolean; }
export interface AgentResult { id: string; status: AgentStatus; output?: string; error?: string; startedAt?: string; completedAt: string; durationMs: number; }
export interface BackgroundHandle { readonly id: string; readonly parentId?: string; readonly sessionId: string; wait(timeoutMs?: number): Promise<AgentResult>; cancel(): boolean; steer(instruction: string): boolean; }
export type AgentCompletionSink = (result: AgentResult) => void | Promise<void>;
export interface AgentCompletionEvent { readonly type: "agent.completed"; readonly agentId: string; readonly parentId?: string; readonly parentSessionId?: string; readonly sessionId: string; readonly background: boolean; readonly result: AgentResult; }
export type AgentEventSink = (event: AgentCompletionEvent) => void | Promise<void>;
export interface RunnerContext { signal: AbortSignal; spec: Required<Pick<AgentSpec, "id" | "task">> & AgentSpec; task: string; profile?: Profile; provider?: string; model?: string; cwd: string; instructions: readonly string[]; steering: readonly string[]; }
export type Runner = (ctx: RunnerContext) => Promise<string>;

/** Build a real Pi child-session runner. The child is deliberately prevented
 * from recursively spawning this control surface; the parent owns orchestration. */
export function createPiRunner(pi: any): Runner {
  return async (ctx) => {
    if (typeof pi?.exec !== "function") return defaultRunner(ctx);
    const sessionDir = `${ctx.cwd}/.pi/agent-sessions`;
    await mkdir(sessionDir, { recursive: true });
    const sessionPath = `${sessionDir}/${ctx.spec.sessionId ?? ctx.spec.id}.jsonl`;
    const args = ["--mode", "text", "--print", "--session", sessionPath, "--exclude-tools", "Agent,AgentControl", "-p", ctx.task];
    if (ctx.provider) args.unshift("--provider", ctx.provider);
    if (ctx.model) args.unshift("--model", ctx.model);
    const result = await pi.exec("pi", args, { cwd: ctx.cwd, signal: ctx.signal });
    if (result?.killed || result?.code !== 0) throw new Error(`child pi failed (${result?.killed ? "killed" : `exit ${result?.code}`}): ${(result?.stderr ?? "").trim()}`);
    return String(result?.stdout ?? "").trim();
  };
}

const clone = <T>(v: T): T => structuredClone(v);
const unique = (xs: readonly string[]) => [...new Set(xs.filter(Boolean))];
const stableId = (parentId: string | undefined, sessionId: string, task: string) => `agent-${createHash("sha256").update(`${parentId ?? "root"}\n${sessionId}\n${task}`).digest("hex").slice(0, 20)}`;

export class AgentManager {
  private readonly agents = new Map<string, { spec: AgentSpec; result?: AgentResult; promise: Promise<AgentResult>; abort: AbortController; steering: string[]; listeners: Set<(r: AgentResult) => void> }>();
  private active = 0;
  private readonly queue: (() => void)[] = [];
  private readonly profiles = new Map<string, Profile>();
  private readonly presets = new Map<string, Preset>();
  private readonly eventSinks = new Set<AgentEventSink>();
  constructor(private readonly options: { runner?: Runner; cwd?: string; concurrency?: number; profiles?: Profile[]; presets?: Record<string, Preset>; onComplete?: AgentCompletionSink; eventSink?: AgentEventSink } = {}) {
    if (options.eventSink) this.eventSinks.add(options.eventSink);
    for (const p of options.profiles ?? []) this.profiles.set(p.name, clone(p));
    for (const [name, p] of Object.entries(options.presets ?? {})) this.presets.set(name, { ...clone(p), name: p.name || name });
  }
  addProfile(profile: Profile): void { this.profiles.set(profile.name, clone(profile)); }
  addEventSink(sink: AgentEventSink): () => void { this.eventSinks.add(sink); return () => this.eventSinks.delete(sink); }
  addPreset(name: string, preset: Preset): void { this.presets.set(name, { ...clone(preset), name: preset.name || name }); }
  profile(name: string): Profile | undefined { const p = this.profiles.get(name); return p && clone(p); }
  private resolve(spec: AgentSpec) {
    const parent = spec.parentId ? this.agents.get(spec.parentId) : undefined;
    const parentSpec = parent?.spec;
    const profile = spec.profile ? this.profiles.get(spec.profile) : parentSpec?.profile ? this.profiles.get(parentSpec.profile) : undefined;
    const preset = spec.preset ? this.presets.get(spec.preset) : undefined;
    const parentPreset = parentSpec?.preset ? this.presets.get(parentSpec.preset) : undefined;
    return { profile: profile ?? preset, provider: spec.provider ?? preset?.provider ?? parentSpec?.provider ?? parentPreset?.provider, model: spec.model ?? preset?.model ?? parentSpec?.model ?? parentPreset?.model, capabilities: unique([...(parentPreset?.capabilities ?? []), ...(parentPreset?.capabilities ?? []), ...(preset?.capabilities ?? []), ...(profile?.capabilities ?? []), ...(spec.capabilities ?? [])]), worktree: spec.worktree ?? preset?.worktree ?? false };
  }
  spawn(spec: AgentSpec): BackgroundHandle {
    if (!spec.task?.trim()) throw new Error("agent task is required");
    const sessionId = spec.sessionId ?? (spec.parentId ? `session:${spec.parentId}` : `session:${stableId(spec.parentId, "root", spec.task)}`);
    const id = spec.id ?? stableId(spec.parentId, sessionId, spec.task); if (this.agents.has(id)) throw new Error(`agent ${id} already exists`);
    const abort = new AbortController(); const steering: string[] = []; const listeners = new Set<(r: AgentResult) => void>();
    let resolve!: (r: AgentResult) => void; const promise = new Promise<AgentResult>(r => resolve = r);
    const entry = { spec: { ...spec, id }, abort, steering, listeners, promise, result: undefined as AgentResult | undefined }; this.agents.set(id, entry);
    const run = () => { this.active++; void this.execute(entry.spec, sessionId, entry).then(r => { entry.result = r; resolve(r); for (const l of listeners) l(clone(r)); const result = clone(r); if (this.options.onComplete) void Promise.resolve(this.options.onComplete(result)).catch(() => undefined); if (spec.background) for (const sink of this.eventSinks) void Promise.resolve(sink({ type: "agent.completed", agentId: r.id, parentId: spec.parentId, parentSessionId: spec.parentSessionId, sessionId, background: true, result })).catch(() => undefined); }).finally(() => { this.active--; this.drain(); }); };
    if (this.active < Math.max(1, this.options.concurrency ?? 4)) run(); else this.queue.push(run);
    return { id, parentId: spec.parentId, sessionId, wait: (timeoutMs?: number) => timeout(promise, timeoutMs), cancel: () => { if (entry.result) return false; abort.abort(); return true; }, steer: (instruction: string) => { if (entry.result || !instruction.trim()) return false; steering.push(instruction); return true; } };
  }
  private drain() { const limit = Math.max(1, this.options.concurrency ?? 4); while (this.active < limit && this.queue.length) this.queue.shift()!(); }
  private async execute(spec: AgentSpec, sessionId: string, entry: { abort: AbortController; steering: string[] }): Promise<AgentResult> {
    const started = Date.now(), startedAt = new Date(started).toISOString(), resolved = this.resolve(spec); let cwd = this.options.cwd ?? process.cwd();
    if (resolved.worktree) cwd = await this.createWorktree(cwd, spec.id!);
    const instructions = [...(resolved.profile?.systemPrompt ? [resolved.profile.systemPrompt] : []), ...(resolved.capabilities ?? []).map(c => `Capability: ${c}`)];
    try { const output = await (this.options.runner ?? defaultRunner)({ signal: entry.abort.signal, spec: { ...spec, id: spec.id!, sessionId }, profile: resolved.profile, provider: resolved.provider, model: resolved.model, task: spec.task, cwd, instructions, steering: entry.steering }); const result: AgentResult = { id: spec.id!, status: entry.abort.signal.aborted ? "cancelled" : "completed", output, startedAt, completedAt: new Date().toISOString(), durationMs: Date.now() - started }; return result; }
    catch (e) { return { id: spec.id!, status: entry.abort.signal.aborted ? "cancelled" : "failed", error: e instanceof Error ? e.message : String(e), startedAt, completedAt: new Date().toISOString(), durationMs: Date.now() - started }; }
  }
  private async createWorktree(cwd: string, id: string) { const path = `${cwd}/.pi-worktrees/${id}`; await mkdir(`${cwd}/.pi-worktrees`, { recursive: true }); await execFileAsync("git", ["worktree", "add", "--detach", path, "HEAD"], { cwd, timeout: 15000 }); return path; }
  get(id: string): AgentResult | undefined { const r = this.agents.get(id)?.result; return r && clone(r); }
  control(id: string, action: "wait" | "cancel" | "steer", value?: string, timeoutMs?: number): Promise<AgentResult | boolean> | boolean { const e = this.agents.get(id); if (!e) throw new Error(`agent ${id} not found`); if (action === "wait") return timeout(e.promise, timeoutMs); if (action === "cancel") { if (e.result) return false; e.abort.abort(); return true; } if (e.result || !value?.trim()) return false; e.steering.push(value); return true; }
  list(): AgentResult[] { return [...this.agents.values()].flatMap(x => x.result ? [clone(x.result)] : []); }
  onComplete(id: string, listener: (result: AgentResult) => void): () => void { const e = this.agents.get(id); if (!e) throw new Error(`agent ${id} not found`); e.listeners.add(listener); if (e.result) listener(clone(e.result)); return () => e.listeners.delete(listener); }
}

async function defaultRunner(ctx: RunnerContext): Promise<string> { if (ctx.signal.aborted) throw new DOMException("Aborted", "AbortError"); return `[${ctx.provider ?? "default"}/${ctx.model ?? "default"}] ${ctx.task}`; }
function timeout<T>(promise: Promise<T>, ms?: number): Promise<T> { if (ms === undefined) return promise; return Promise.race([promise, new Promise<T>((_, reject) => setTimeout(() => reject(new Error("agent wait timed out")), ms))]); }

export function registerAgents(pi: any, manager = new AgentManager(), parentSessionId?: string): AgentManager {
  const targetSessionId = parentSessionId ?? pi?.getSessionId?.() ?? pi?.sessionId;
  manager.addEventSink(event => {
    if (!event.background || !targetSessionId || event.parentSessionId !== targetSessionId || typeof pi?.sendUserMessage !== "function") return;
    const { result } = event;
    const output = result.output !== undefined ? `\noutput: ${result.output}` : "";
    const error = result.error !== undefined ? `\nerror: ${result.error}` : "";
    pi.sendUserMessage(`[agent completed] id=${result.id} status=${result.status}${output}${error}`, { deliverAs: "followUp" });
  });
  pi.registerTool({ name: "Agent", label: "Run agent", description: "Start a child agent in the inherited session context.", parameters: { type: "object", required: ["task"], properties: { task: { type: "string" }, profile: { type: "string" }, provider: { type: "string" }, model: { type: "string" }, background: { type: "boolean" }, worktree: { type: "boolean" } } }, async execute(_id: string, input: any, ctx: any) { const currentSessionId = ctx?.sessionManager?.getSessionId?.() ?? ctx?.sessionId ?? targetSessionId; const parentId = ctx?.agentId ?? currentSessionId; const h = manager.spawn({ ...input, parentId, parentSessionId: currentSessionId, sessionId: currentSessionId, background: Boolean(input.background) }); const result = input.background ? { handle: h.id, sessionId: h.sessionId } : await h.wait(); return { content: [{ type: "text", text: JSON.stringify(result) }], details: result }; } });
  pi.registerTool({ name: "AgentControl", label: "Control agent", description: "Wait, cancel, or steer a background agent.", parameters: { type: "object", required: ["id", "action"], properties: { id: { type: "string" }, action: { type: "string", enum: ["wait", "cancel", "steer"] }, instruction: { type: "string" }, timeoutMs: { type: "number" } } }, async execute(_id: string, input: any) { const value = input.action === "wait" ? await manager.control(input.id, "wait", undefined, input.timeoutMs) : manager.control(input.id, input.action, input.instruction); return { content: [{ type: "text", text: JSON.stringify(value) }], details: value }; } });
  return manager;
}

export * from "./contracts.js";
export * from "./control-plane.js";
export * from "./control-plane-store.js";
export * from "./control-plane-transport.js";

/** Stable, JSON-safe runtime contracts shared by Pi adapters and hosts. */

export type ID = string & { readonly __brand: "StableID" };
const ID_RE = /^[a-zA-Z0-9][a-zA-Z0-9._:-]{0,127}$/;
export function createId(value: string): ID {
  if (!ID_RE.test(value)) throw new ContractError("invalid_id", `Invalid stable ID: ${JSON.stringify(value)}`);
  return value as ID;
}
export function newId(prefix = "evt"): ID {
  const suffix = globalThis.crypto?.randomUUID?.() ?? `${Date.now().toString(36)}-${Math.random().toString(36).slice(2)}`;
  return createId(`${prefix}:${suffix}`);
}

export const POLICY_CLASSES = ["KEEP", "OPT-IN", "DEFER-DISCOVER", "NEVER-DEFAULT"] as const;
export type PolicyClass = typeof POLICY_CLASSES[number];
export interface Capability { id: ID; aliases?: string[]; policy: PolicyClass; sideEffect?: string; hostBound?: boolean; credentialBound?: boolean; }
export interface CapabilitySet { capabilities: Capability[]; selected: ID[]; }

export interface PolicyContext {
  actorId: ID; sessionId: ID; capabilities: ReadonlySet<ID> | ID[];
  profileId?: ID; workspace?: string; consent?: "granted" | "denied" | "required";
  metadata?: JsonObject;
}

export const EVENT_KINDS = ["started", "progress", "content", "tool_call", "tool_result", "completed", "failed", "cancelled"] as const;
export type EventKind = typeof EVENT_KINDS[number];
export interface RuntimeEvent<T extends JsonValue = JsonValue> { id: ID; sequence: number; kind: EventKind; sessionId: ID; timestamp: string; payload?: T; redacted?: boolean; }
export function normalizeEvent<T extends JsonValue>(event: Omit<RuntimeEvent<T>, "timestamp"> & { timestamp?: string }): RuntimeEvent<T> {
  if (!Number.isSafeInteger(event.sequence) || event.sequence < 0) throw new ContractError("invalid_sequence", "Event sequence must be a non-negative safe integer");
  return { ...event, timestamp: event.timestamp ?? new Date().toISOString() };
}

export const OUTCOMES = ["success", "rejected", "denied", "timeout", "cancelled", "failed"] as const;
export type Outcome = typeof OUTCOMES[number];
export interface Success<T> { ok: true; outcome: "success"; value: T; }
export interface Failure { ok: false; outcome: Exclude<Outcome, "success">; error: RuntimeError; }
export type Result<T> = Success<T> | Failure;
export const ok = <T>(value: T): Success<T> => ({ ok: true, outcome: "success", value });
export const err = (outcome: Failure["outcome"], error: RuntimeError): Failure => ({ ok: false, outcome, error });

export type ErrorCode = "invalid_id" | "invalid_sequence" | "validation" | "not_found" | "denied" | "conflict" | "storage" | "internal";
export interface RuntimeError { code: ErrorCode; message: string; retryable?: boolean; cause?: string; details?: JsonObject; }
export class ContractError extends Error {
  readonly code: ErrorCode;
  constructor(code: ErrorCode, message: string, readonly details?: JsonObject) { super(message); this.name = "ContractError"; this.code = code; }
}

export type AuditOutcome = "success" | "failure" | "denied" | "blocked";
export interface AuditRecord { id: ID; timestamp: string; sessionId: ID; eventType: string; actorId: ID; action: string; resource?: string; outcome: AuditOutcome; details?: JsonObject; }
export interface AuditQuery { sessionId?: ID; actorId?: ID; eventTypes?: string[]; outcomes?: AuditOutcome[]; from?: string; to?: string; limit?: number; }
export interface AuditSink { append(record: AuditRecord): Promise<void>; query?(query: AuditQuery): Promise<AuditRecord[]>; }

export interface Profile { id: ID; provider: string; model: string; systemPrompt?: string; capabilities?: ID[]; limits?: { maxTurns?: number; timeoutMs?: number }; metadata?: JsonObject; }
export interface ProfileStore { get(id: ID): Promise<Profile | undefined>; list(): Promise<Profile[]>; put(profile: Profile): Promise<void>; delete(id: ID): Promise<void>; }
export interface EventStore { append(event: RuntimeEvent): Promise<void>; read(sessionId: ID, afterSequence?: number): Promise<RuntimeEvent[]>; }
export interface RuntimePersistence { events: EventStore; profiles: ProfileStore; audit: AuditSink; }

export type JsonPrimitive = string | number | boolean | null;
export type JsonValue = JsonPrimitive | JsonValue[] | { [key: string]: JsonValue };
export type JsonObject = { [key: string]: JsonValue };
const SECRET = /token|secret|password|api[-_]?key|authorization|credential/i;
export function redact<T extends JsonValue>(value: T): T {
  if (Array.isArray(value)) return value.map(redact) as T;
  if (value && typeof value === "object") {
    const out: JsonObject = {};
    for (const [key, item] of Object.entries(value)) out[key] = SECRET.test(key) ? "[REDACTED]" : redact(item);
    return out as T;
  }
  return value;
}
export function redactRecord(record: AuditRecord): AuditRecord { return { ...record, details: record.details ? redact(record.details) : undefined }; }

/** Redacts nested secrets without mutating the input; suitable for explain/audit surfaces. */
export function redactUnknown(value: unknown): unknown {
  if (Array.isArray(value)) return value.map(redactUnknown);
  if (value && typeof value === "object") {
    const out: Record<string, unknown> = {};
    for (const [key, item] of Object.entries(value)) out[key] = SECRET.test(key) ? "[REDACTED]" : redactUnknown(item);
    return out;
  }
  return value;
}

{
  "name": "@pi-swarm/runtime-contracts",
  "private": true,
  "type": "module",
  "scripts": { "build": "tsc -p tsconfig.json", "test": "vitest run test" },
  "devDependencies": { "@types/node": "^22.0.0", "typescript": "^5.9.0", "vitest": "^3.2.0" }
}

import { describe, expect, it } from "vitest";
import { mkdtempSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { AgentManager, createPiRunner, registerAgents } from "../src/index.js";

describe("AgentManager", () => {
  it("runs a real Pi child with isolated control tools and inherited execution context", async () => {
    let seen: any;
    const cwd = mkdtempSync(join(tmpdir(), "pi-agent-runner-"));
    const runner = createPiRunner({ exec: async (...args: any[]) => { seen = args; return { code: 0, stdout: "child result", stderr: "", killed: false }; } });
    expect(await runner({ signal: new AbortController().signal, spec: { id: "x", task: "inspect" }, task: "inspect", cwd, instructions: [], steering: [] })).toBe("child result");
    expect(seen[0]).toBe("pi");
    expect(seen[1]).toEqual(expect.arrayContaining(["--mode", "text", "--session", `${cwd}/.pi/agent-sessions/x.jsonl`, "--exclude-tools", "Agent,AgentControl", "-p", "inspect"]));
    expect(seen[2]).toMatchObject({ cwd });
  });

  it("inherits profile capabilities and preserves parent identity", async () => {
    let seen: any;
    const manager = new AgentManager({ profiles: [{ name: "review", systemPrompt: "be precise", capabilities: ["read"] }], runner: async ctx => { seen = ctx; return "done"; } });
    const parent = manager.spawn({ id: "parent", task: "parent", profile: "review", provider: "openai", model: "gpt-test" });
    await parent.wait();
    const child = manager.spawn({ id: "child", task: "child", parentId: parent.id });
    expect(await child.wait()).toMatchObject({ id: "child", status: "completed", output: "done" });
    expect(seen.spec.parentId).toBe("parent");
    expect(seen.provider).toBe("openai");
    expect(seen.model).toBe("gpt-test");
    expect(seen.instructions).toContain("be precise");
    expect(seen.instructions).toContain("Capability: read");
  });
  it("supports cancellation and bounded concurrency", async () => {
    let running = 0, maximum = 0;
    const manager = new AgentManager({ concurrency: 1, runner: async ({ signal }) => { running++; maximum = Math.max(maximum, running); await new Promise<void>(resolve => { const timer = setTimeout(resolve, 30); signal.addEventListener("abort", () => { clearTimeout(timer); resolve(); }, { once: true }); }); running--; return "ok"; } });
    const first = manager.spawn({ id: "a", task: "a" });
    const second = manager.spawn({ id: "b", task: "b" });
    first.cancel();
    expect((await first.wait()).status).toBe("cancelled");
    expect((await second.wait()).status).toBe("completed");
    expect(maximum).toBe(1);
  });
  it("notifies an injected parent event sink when background work completes", async () => {
    const events: any[] = [];
    const manager = new AgentManager({ runner: async () => "done", eventSink: event => { events.push(event); } });
    const handle = manager.spawn({ id: "child", parentId: "parent-session", parentSessionId: "parent-session", sessionId: "session-1", task: "work", background: true });
    await handle.wait();
    expect(events).toHaveLength(1);
    expect(events[0]).toMatchObject({ type: "agent.completed", agentId: "child", parentId: "parent-session", parentSessionId: "parent-session", sessionId: "session-1", background: true, result: { status: "completed", output: "done" } });
  });
  it("wires background completion to the exact parent Pi session once", async () => {
    const tools: any[] = [], messages: any[] = [];
    const pi = { sessionId: "parent-session", registerTool: (tool: any) => tools.push(tool), sendUserMessage: (content: string, options: any) => messages.push({ content, options }) };
    const manager = new AgentManager({ runner: async () => "finished" });
    registerAgents(pi, manager);
    const agent = tools.find(tool => tool.name === "Agent");
    const result = await agent.execute("call", { task: "work", background: true }, { sessionId: "parent-session" });
    await manager.control(result.details.handle, "wait");
    expect(messages).toHaveLength(1);
    expect(messages[0]).toEqual({ content: expect.stringContaining("id=agent"), options: { deliverAs: "followUp" } });
    expect(messages[0].content).toContain("status=completed");
    expect(messages[0].content).toContain("output: finished");
    await manager.control(result.details.handle, "wait");
    expect(messages).toHaveLength(1);

    const otherMessages: any[] = [];
    const otherPi = { sessionId: "other-session", registerTool: () => undefined, sendUserMessage: (content: string) => otherMessages.push(content) };
    registerAgents(otherPi, manager);
    expect(otherMessages).toHaveLength(0);
  });
  it("does not emit completion for foreground agents", async () => {
    const messages: any[] = [], pi = { sessionId: "parent", registerTool: (tool: any) => messages.push(tool), sendUserMessage: () => { throw new Error("must not notify"); } };
    const manager = new AgentManager({ runner: async () => "done" });
    registerAgents(pi, manager);
    const agent = messages.find(tool => tool.name === "Agent");
    await agent.execute("call", { task: "work" }, { sessionId: "parent" });
  });
  it("steers a running agent and emits completion", async () => {
    const manager = new AgentManager({ runner: async ({ signal, spec }) => { await new Promise(r => setTimeout(r, 5)); if (signal.aborted) throw new Error("cancelled"); return spec.task; } });
    const handle = manager.spawn({ id: "x", task: "work" });
    expect(handle.steer("focus")).toBe(true);
    let completed = false; manager.onComplete("x", () => { completed = true; });
    expect((await handle.wait()).output).toBe("work"); expect(completed).toBe(true);
  });
});

/**
 * Agent loop that works with AgentMessage throughout.
 * Transforms to Message[] only at the LLM call boundary.
 */

import {
	type AssistantMessage,
	type Context,
	EventStream,
	streamSimple,
	type ToolResultMessage,
	validateToolArguments,
} from "@earendil-works/pi-ai";
import type {
	AgentContext,
	AgentEvent,
	AgentLoopConfig,
	AgentMessage,
	AgentTool,
	AgentToolCall,
	AgentToolResult,
	StreamFn,
} from "./types.ts";

export type AgentEventSink = (event: AgentEvent) => Promise<void> | void;

/**
 * Start an agent loop with a new prompt message.
 * The prompt is added to the context and events are emitted for it.
 */
export function agentLoop(
	prompts: AgentMessage[],
	context: AgentContext,
	config: AgentLoopConfig,
	signal?: AbortSignal,
	streamFn?: StreamFn,
): EventStream<AgentEvent, AgentMessage[]> {
	const stream = createAgentStream();

	void runAgentLoop(
		prompts,
		context,
		config,
		async (event) => {
			stream.push(event);
		},
		signal,
		streamFn,
	).then((messages) => {
		stream.end(messages);
	});

	return stream;
}

/**
 * Continue an agent loop from the current context without adding a new message.
 * Used for retries - context already has user message or tool results.
 *
 * **Important:** The last message in context must convert to a `user` or `toolResult` message
 * via `convertToLlm`. If it doesn't, the LLM provider will reject the request.
 * This cannot be validated here since `convertToLlm` is only called once per turn.
 */
export function agentLoopContinue(
	context: AgentContext,
	config: AgentLoopConfig,
	signal?: AbortSignal,
	streamFn?: StreamFn,
): EventStream<AgentEvent, AgentMessage[]> {
	if (context.messages.length === 0) {
		throw new Error("Cannot continue: no messages in context");
	}

	if (context.messages[context.messages.length - 1].role === "assistant") {
		throw new Error("Cannot continue from message role: assistant");
	}

