          );
          await ctx.completeStep(outage, { simulated: true });
          throw new Error("temporary email provider outage");
        }

        const delivery = await ctx.step("send-activation-email", async () => {
          console.log(
            `[${ctx.taskID}] sending activation email to ${user.email}`,
          );
          return {
            sent: true,
            provider: "demo-mail",
            to: user.email,
